import { createApi, fetchBaseQuery } from "@reduxjs/toolkit/query/react"; // ✅ use /react here
import { setLoggedIn, setLoggedOut } from "./AuthSlice";
import type { RootState } from "./store";
import type { LoginVerifyTotpResponseData } from "../interfaces/AuthInterfaces";

const environment = import.meta.env;

const baseQuery = fetchBaseQuery({
  baseUrl: environment.VITE_API_BASE_URL,
  credentials: "include",
  prepareHeaders: (headers, { getState }) => {
    const token = (getState() as RootState).auth.accessToken;

    if (token) {
      headers.set("authorization", `Bearer ${token}`);
    }
    return headers;
  },

  responseHandler: async (response) => {
    const contentType = response.headers.get("content-type");

    if (contentType?.includes("application/pdf")) {
      return await response.blob(); // 👈 IMPORTANT
    }

    if (contentType?.includes("application/json")) {
      return await response.json();
    }

    return await response.text();
  },
});

const baseQueryWithReauth = async (args: any, api: any, extraOptions: any) => {
  let result = await baseQuery(args, api, extraOptions);

  if (result?.error?.status === 401) {
    const refreshResult = await baseQuery(
      { url: "/auth/refresh", method: "POST" },
      api,
      extraOptions,
    );

    if (refreshResult?.data) {
      const { accessToken, user } =
        refreshResult.data as LoginVerifyTotpResponseData;

      const payload = {
        _id: user._id,
        email: user.email,
        firstName: user.firstName,
        lastName: user.lastName,
        phoneNo: user.phoneNo,
        profilePic: user.profilePic,
        role: user.role,
        slug: user.slug,
        status: user.status,
        createdAt: user.createdAt,
        title: user.title || "",
        hireDate: new Date(user.hireDate).toISOString(),
        customPermissions: user.customPermissions || [],
        isFacilityManager: user.isFacilityManager,
      };
      api.dispatch(
        setLoggedIn({
          accessToken,
          UserData: payload,
        }),
      );

      result = await baseQuery(args, api, extraOptions);
    } else {
      api.dispatch(setLoggedOut());
    }
  }

  return result;
};

// ✅ Create the API with endpoints directly
export const api = createApi({
  reducerPath: "api",
  refetchOnFocus: false,
  refetchOnReconnect: false,
  baseQuery: baseQueryWithReauth,
  tagTypes: [
    "Event",
    "Ticket",
    "Manual",
    "Meetings",
    "HrUpdates",
    "StaffFeedBack",
    "IncidentReport",
    "Profile",
    "FAQ",
    "EmergencyContact",
    "Employees",
    "OrgNode",
    "Notification",
    "Announcement",
    "Agreement",
    "client-incident",
    "client-feedback",
    "employee-incident",
    "payment-requistion",
    "functional-abilty",
    "media-consent",
    "Locations",
    "Task",
    "Certification",
    "TicketCategory",
    "CommentNotification",
  ],
  endpoints: () => ({}),
});

// ✅ Export hooks directly from api
export const {} = api;
